import unicodedata, json, sys
P = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\13-11-2026\521113-16\521113-16_ALL.dxf'
FLAGS = json.load(open(r'C:\Users\DELL\AppData\Local\Temp\ai_cad_521113-16\flags.json', encoding='utf8'))
L = open(P, 'rb').read().decode('cp932').split('\r\n')
s = L.index('ENTITIES')
e = L.index('ENDSEC', s)
body = L[s + 1:e]
ents = []
cur = None
for i in range(0, len(body) - 1, 2):
    c, v = body[i], body[i + 1]
    if c.strip() == '0':
        cur = [(c, v)]
        ents.append(cur)
    else:
        cur.append((c, v))


def getv(en, code):
    for c, v in en:
        if c.strip() == code:
            return v
    return None


keep = []
removed = []
for en in ents:
    if en[0][1] == 'TEXT' and getv(en, '62') == '6' and float(getv(en, '10')) == -150.0:
        removed.append(en)
    else:
        keep.append(en)
print('removed', len(removed), 'keep', len(keep))
tpl = removed[0]
ty = None
for en in keep:
    if en[0][1] == 'TEXT' and getv(en, '1') == '068428':
        ty = float(getv(en, '20'))
print('ty', ty)


def esc(t):
    t = unicodedata.normalize('NFC', t)
    return ''.join(ch if ord(ch) < 128 else '\\U+%04X' % ord(ch) for ch in t)


def wrap(t, n=40):
    out = []
    cur = ''
    for w in t.split(' '):
        if cur and len(cur) + 1 + len(w) > n:
            out.append(cur)
            cur = w
        else:
            cur = (cur + ' ' + w) if cur else w
    if cur:
        out.append(cur)
    return out


hs = L.index('$HANDSEED')
seed = int(L[hs + 2], 16)
handles = [getv(en, '5') for en in removed]
lines = []
for fl in FLAGS:
    lines += wrap(fl)
new = []
k = 0
for ln in lines:
    en = [list(x) for x in tpl]
    for x in en:
        c = x[0].strip()
        if c == '5':
            if k < len(handles):
                x[1] = handles[k]
            else:
                x[1] = '%X' % seed
                seed += 1
        elif c == '20':
            x[1] = '%g' % (ty - 12 - 7 * k)
        elif c == '1':
            x[1] = esc(ln)
    new.append(en)
    k += 1
print('lines', len(lines))
out = L[:s + 1]
for en in keep + new:
    for c, v in en:
        out += [c, v]
out += L[e:]
hs = out.index('$HANDSEED')
out[hs + 2] = '%X' % seed if seed > int(L[hs + 2], 16) else out[hs + 2]
open(P, 'wb').write('\r\n'.join(out).encode('cp932'))
print('ok')

